import { BrowserRouter as Router,Route} from "react-router-dom";
import './App.css';
import Header from './Components/Header';
import Footer from './Components/footer';




function App() {
  return (
    <div className="App">
      <Router>
          <Route path="/Header" element={<Header />} />
          <Route path="/Footer" element={<Footer />} />
          <></>

      </Router>

      </div>

  );
}


export default App;
